INSERT INTO TBL_CODE_PARENT (PCODE,PCODE_NM,PCODE_MEMO,PCODE_SEQ_NO,REG_DATE)
SELECT 'NOTE_TAG','비밀 메모 태그','확장값은 저장할 태그 값입니다. 계정의 확장값은 계정으로 유지하세요.',10,NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TBL_CODE_PARENT WHERE PCODE='NOTE_TAG');
INSERT INTO TBL_CODE_PARENT (PCODE,PCODE_NM,PCODE_MEMO,PCODE_SEQ_NO,REG_DATE)
SELECT 'POST_BLOCK','본문 색상 블록','코드=CSS 클래스명, 확장값=배경색, 추가 정보01=테두리색, 추가 정보02=글자색. 색상은 #RRGGBB 형식입니다.',20,NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TBL_CODE_PARENT WHERE PCODE='POST_BLOCK');
